from datetime import timedelta

import config
import database
import models
import recommender
import support


class UniClubsLearningTests(support.DatabaseCase):
    """Build real training frames with an isolated original schema and public domain objects."""

    def setUp(self):
        """Create a genuine local profile in the in-memory original database only."""
        super().setUp()
        self.user_id = database.create_user(self.connection, 'Alex', now=support.NOW)
        database.set_user_directions(self.connection, self.user_id, {'career'})
        self.profile = database.get_user_profile(self.connection, self.user_id)

    def example(self, identifier='one', rating=5, start=None, answered=None):
        """Return one private source rating without persisting its event in the old catalog."""
        start = start or support.NOW - timedelta(days=2)
        event = models.ClubEvent(
            event_id='uniclubs:' + identifier, series_id='uniclubs-series:' + identifier,
            title='Source workshop', start=start, end=start + timedelta(hours=1),
            location='SQUARE', location_type='st_gallen', direction_key='career',
            bundle_key='career_tech', bundle_name='Tech & data',
            club_id='uniclubs-club:source-club', club_name='Source Club')
        return {'event': event, 'profile': self.profile, 'rating': rating,
                'answered_at': database.to_db_text(answered or support.NOW)}

    def test_genuine_source_feedback_has_weight_five_without_catalog_copies(self):
        """Use source domain objects directly and retain identifiers outside model features."""
        example = self.example()
        self.profile.favorite_series_ids.add(example['event'].series_id)
        X, labels, weights = recommender.build_training_data(
            self.connection, now=support.NOW, public_examples=[example])
        self.assertEqual(len(X), 1)
        self.assertEqual(labels.tolist(), [1])
        self.assertEqual(weights.tolist(), [config.REAL_USER_SAMPLE_WEIGHT])
        self.assertEqual(X.iloc[0]['fav_series'], 1)
        for column in X.columns:
            self.assertNotIn('event_id', column)
            self.assertNotIn('user_id', column)
            self.assertNotIn('uniclubs:', column)
        for table_query in ('SELECT count(*) FROM events', 'SELECT count(*) FROM series',
                            'SELECT count(*) FROM interactions'):
            self.assertEqual(self.connection.execute(table_query).fetchone()[0], 0)

    def test_same_start_ratings_do_not_leak_into_peer_history(self):
        """Own labels and same-time peers must not change earlier bundle-rating features."""
        examples = [self.example('first', rating=1), self.example('second', rating=4)]
        X, labels, weights = recommender.build_training_data(
            self.connection, now=support.NOW, public_examples=examples)
        self.assertEqual(labels.tolist(), [0, 1])
        self.assertEqual(X['earlier_avg_rating_in_bundle'].tolist(),
                         [config.NEUTRAL_RATING, config.NEUTRAL_RATING])
        later = self.example('third', rating=4, start=support.NOW - timedelta(days=1))
        X, labels, weights = recommender.build_training_data(
            self.connection, now=support.NOW, public_examples=examples + [later])
        self.assertAlmostEqual(X.iloc[2]['earlier_avg_rating_in_bundle'], 2.5)

    def test_future_events_and_answers_are_excluded(self):
        """Unavailable future feedback cannot enter the source training matrix."""
        examples = [self.example('future-event', start=support.NOW + timedelta(hours=1)),
                    self.example('future-answer', answered=support.NOW + timedelta(seconds=1))]
        X, labels, weights = recommender.build_training_data(
            self.connection, now=support.NOW, public_examples=examples)
        self.assertEqual((len(X), len(labels), len(weights)), (0, 0, 0))

    def test_unknown_answer_time_is_excluded_without_crashing(self):
        """An old nullable answer timestamp cannot establish available training history."""
        example = self.example()
        example['answered_at'] = None
        X, labels, weights = recommender.build_training_data(
            self.connection, now=support.NOW, public_examples=[example])
        self.assertEqual((len(X), len(labels), len(weights)), (0, 0, 0))

    def test_invalid_source_rating_is_rejected(self):
        """The new source must obey the same one-to-five integer rating contract."""
        for invalid in (True, None, 0, 6, '5', 4.5):
            with self.subTest(rating=invalid):
                with self.assertRaises(ValueError):
                    recommender.build_training_data(
                        self.connection, now=support.NOW,
                        public_examples=[self.example(rating=invalid)])
